import path from "node:path";

import { test } from "@playwright/test";

import { signIn } from "./helpers";
import { SCREENS } from "./screens";

const OUT = path.resolve(import.meta.dirname, "../../../docs/images");

/** The 9 screenshots in docs/images (synthetic data only), regenerated by `make docs`. */
test.describe("screenshots", () => {
  test.use({ viewport: { width: 1440, height: 900 } });
  for (const [i, screen] of SCREENS.entries()) {
    test(screen.name, async ({ page }) => {
      await signIn(page, screen.persona);
      await screen.open(page);
      await page.screenshot({
        path: path.join(OUT, `${String(i + 1).padStart(2, "0")}-${screen.name}.png`),
        fullPage: false, // the 1440×900 viewport keeps the images small
      });
    });
  }
});
